      const plan=(await runtime.db.execute(sql`EXPLAIN (ANALYZE, FORMAT JSON) SELECT * FROM hosted_allowance_read(${wid},1,0,100,1000,10000,10)`)).rows[0]['QUERY PLAN'] as Json[];
